(function () {
  'use strict';
  const D = window.AQData;
  const icon = window.AQIcons;
  const $ = (q, root = document) => root.querySelector(q);
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const normalize = text => String(text).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
  const state = {user:null, services:[], reviews:[], reports:[], profile:null, photo:null, professionalAccount:null, subscriptions:{}, clientIds:new Map([['cliente@exemplo.test','demo-client']])};
  const ownsLocalProfile = () => Boolean(state.profile) && state.user?.role === 'professional' && state.user.proId === state.profile.id;
  const currentSubscription = () => state.user?.role === 'professional' ? state.subscriptions[state.user.proId] || 'inactive' : 'inactive';
  const clientIdFor = email => {if(!state.clientIds.has(email)) state.clientIds.set(email,'local-client-'+state.clientIds.size); return state.clientIds.get(email);};
  let toastTimer;
  let theme = 'praca';
  try {theme = new URLSearchParams(location.search).get('concept') || localStorage.getItem('aq-concept') || theme;} catch {}
  if (!['praca','vivo','editorial'].includes(theme)) theme = 'praca';
  const cityOptions = (selected = '', all = true) => `${all ? '<option value="">Todo o Vale do Paraíba</option>' : '<option value="">Selecione a cidade</option>'}${D.cities.map(c => `<option ${c === selected ? 'selected' : ''} value="${esc(c)}">${esc(c)}</option>`).join('')}`;
  const category = id => D.categories.find(c => c.id === id);
  const professional = id => state.profile?.id === id ? state.profile : D.professionals.find(p => p.id === id);
  const reviewsFor = id => [...D.reviews, ...state.reviews].filter(r => r.proId === id);
  const ratingFor = p => {const reviews = reviewsFor(p.id); return reviews.length ? {score: (reviews.reduce((n,r) => n + r.score, 0) / reviews.length).toFixed(1).replace('.',','), count:reviews.length} : {score:'Novo', count:0};};
  const portrait = (p, extra = '') => p.photo ? `<img class="uploaded-portrait ${extra}" src="${p.photo}" alt="Foto de ${esc(p.name)}">` : `<span class="portrait portrait-${Number(p.photoIndex) || 0} ${extra}" role="img" aria-label="Retrato ilustrativo de ${esc(p.name)}"></span>`;
  const stars = score => `<span class="rating-stars" aria-label="${Number(score)} de 5 estrelas">${[1,2,3,4,5].map(n => `<span class="${n <= Math.round(score) ? 'filled' : ''}">${icon('star',15)}</span>`).join('')}</span>`;
  const tags = p => p.categories.map(id => `<span class="tag">${esc(category(id)?.name || id)}</span>`).join('');
  window.AQCard = p => {
    const rating = ratingFor(p);
    return `<article class="pro-card"><a href="#/profissional/${esc(p.id)}" class="pro-photo" aria-label="Conhecer ${esc(p.name)}">${portrait(p)}<span class="photo-caption">Perfil ilustrativo</span></a><div class="pro-card-body"><div class="pro-card-top"><span class="pro-meta">${icon('pin',15)} ${esc(p.city)}</span><span class="card-rating">${icon('star',15)} ${rating.score} <small>(${rating.count})</small></span></div><h3><a href="#/profissional/${esc(p.id)}">${esc(p.name)}</a></h3><p class="pro-title">${esc(p.title)}</p><div class="pro-tags">${tags(p)}</div><a class="pro-card-link" href="#/profissional/${esc(p.id)}">Conhecer profissional ${icon('arrow',19)}</a></div></article>`;
  };
  function toast(message) {clearTimeout(toastTimer); const el = $('#toast'); el.textContent = message; el.classList.add('visible'); toastTimer = setTimeout(() => el.classList.remove('visible'),4500);}
  function go(path) { if (location.hash === '#' + path) render(); else location.hash = path; }
  function currentRoute() { const value = location.hash.replace(/^#/, '') || '/inicio'; const [path,query] = value.split('?'); return {path, params:new URLSearchParams(query || '')}; }
  function routeLink(path, params) {const q = new URLSearchParams(params); return '#' + path + (q.size ? '?' + q : '');}
  function pageIntro(title, description, back = '/inicio') {return `<a class="back-link" href="#${back}">← Voltar</a><h1>${title}</h1>${description ? `<p class="page-lead">${description}</p>` : ''}`;}
  function demoNote(text = 'Prévia local: use dados fictícios. As informações desta sessão desaparecem ao recarregar a página.') {return `<p class="demo-note">${icon('info',18)}<span>${text}</span></p>`;}
  function searchPage(params) {
    const term = params.get('term') || ''; const city = params.get('city') || ''; const cat = params.get('category') || '';
    const terms = normalize(term).split(/\s+/).filter(Boolean);
    const all = [...D.professionals,...(state.profile?.status === 'published' ? [state.profile] : [])];
    const filtered = all.filter(p => (!city || p.cities.includes(city)) && (!cat || p.categories.includes(cat)) && terms.every(t => normalize([p.name,p.title,...p.skills,...p.categories.map(c => category(c)?.name)].join(' ')).includes(t)));
    return `<section class="search-page container page-section"><div class="search-heading"><div>${pageIntro('Encontre quem resolve.', 'Profissionais que atendem a sua cidade, com as habilidades que você precisa.')}</div><span class="region-marker">${icon('pin',18)} Vale do Paraíba · SP</span></div><form class="results-search" data-search-form><label><span>Qual serviço você precisa?</span><div class="field-icon">${icon('search',20)}<input name="term" value="${esc(term)}" placeholder="Serviço, habilidade ou profissional"></div></label><label><span>Em qual cidade?</span><select name="city">${cityOptions(city)}</select></label><button class="btn btn-primary" type="submit">Buscar ${icon('arrow',19)}</button><input type="hidden" name="category" value="${esc(cat)}"></form><div class="results-layout"><aside class="filters-panel"><h2>${icon('filter',19)} Categorias</h2><a class="filter-link ${!cat ? 'active' : ''}" href="${routeLink('/buscar',{term,city})}">Todas as categorias</a>${D.categories.map(c => `<a class="filter-link ${cat === c.id ? 'active' : ''}" href="${routeLink('/buscar',{term,city,category:c.id})}">${icon(c.icon,20)} ${c.name}${cat === c.id ? icon('check',16) : ''}</a>`).join('')}<p>Um profissional pode atuar em mais de uma categoria.</p></aside><div><div class="results-summary"><h2>${filtered.length} ${filtered.length === 1 ? 'profissional encontrado' : 'profissionais encontrados'}</h2><span>Base demonstrativa</span></div>${city ? `<p class="coverage-note">Atendem <strong>${esc(city)}</strong>, mesmo quando moram em outra cidade.</p>` : ''}${filtered.length ? `<div class="results-grid">${filtered.map(window.AQCard).join('')}</div>` : `<div class="empty-state">${icon('search',42)}<h2>Ainda não encontramos esse encontro.</h2><p>Não há perfis de demonstração para essa combinação. Tente outra habilidade ou escolha uma cidade diferente.</p><a class="btn btn-primary" href="#/buscar">Limpar filtros</a><p class="small-note">A região nunca é ampliada sem você escolher.</p></div>`}</div></div></section>`;
  }
  function reviewCard(r, p) {return `<article class="review-card"><div class="review-header"><div class="review-initial">${esc(r.author.slice(0,1))}</div><div><strong>${esc(r.author)}</strong><span>${esc(r.service)} · ${new Date(r.date + 'T12:00:00').toLocaleDateString('pt-BR')}</span></div>${stars(r.score)}</div><p>${esc(r.text)}</p>${r.photos?.length ? `<div class="review-photos">${r.photos.map((photo,i) => `<a href="${photo}" target="_blank" rel="noopener" aria-label="Abrir foto ${i+1} do serviço"><img src="${photo}" alt="Foto ${i+1} enviada na avaliação"></a>`).join('')}</div>` : ''}${r.response ? `<div class="professional-response"><strong>Resposta do profissional</strong><p>${esc(r.response)}</p></div>` : ''}<div class="review-actions"><span>${r.id.startsWith('local-') ? 'Vinculada ao registro demonstrativo' : 'Avaliação ilustrativa'}</span><button class="text-button" data-report="${esc(r.id)}">${icon('flag',15)} Denunciar</button>${state.user?.role === 'professional' && state.user.proId === p.id && !r.response ? `<button class="text-button" data-respond="${esc(r.id)}">Responder</button>` : ''}</div></article>`;}
  function profilePage(id) {
    const p = professional(id); if (!p) return notFound();
    const rating = ratingFor(p); const reviews = reviewsFor(id);
    return `<section class="container page-section profile-page"><a class="back-link" href="#/buscar">← Voltar para profissionais</a><div class="profile-layout"><div><div class="profile-cover"><div class="profile-avatar">${portrait(p)}</div><div><div class="pro-tags">${tags(p)}</div><h1>${esc(p.name)}</h1><p class="profile-title">${esc(p.title)}</p><p class="pro-meta">${icon('pin',18)} ${esc(p.city)} · SP</p><div class="profile-rating">${icon('star',19)} <strong>${rating.score}</strong> <a href="#reviews">${rating.count} avaliações ilustrativas</a></div></div></div><div class="profile-body"><section><h2>Sobre o meu trabalho</h2><p>${esc(p.description)}</p></section><section><h2>O que eu faço</h2><div class="skills-list">${p.skills.map(s => `<span>${icon('check',18)}${esc(s)}</span>`).join('')}</div></section><section><h2>Cidades que eu atendo</h2><div class="cities-list">${p.cities.map(c => `<span>${icon('pin',15)} ${esc(c)}</span>`).join('')}</div></section><section><h2>Trabalhos e especialidades</h2><p class="muted">As fotos de trabalhos reais serão adicionadas pelo profissional. Aqui, mostramos apenas exemplos de serviços.</p><div class="work-examples">${(p.projects || p.skills.slice(0,2)).map((s,i) => `<div>${icon(category(p.categories[i % p.categories.length])?.icon || 'engineering',30)}<h3>${esc(s)}</h3><span>Exemplo de serviço</span></div>`).join('')}</div></section><section id="reviews"><div class="section-title-row"><h2>Avaliações de quem contratou</h2><span>${rating.count} ${rating.count === 1 ? 'avaliação' : 'avaliações'}</span></div><p class="muted">Relatos positivos e negativos, com espaço para resposta. Nesta prévia, todos os relatos são fictícios.</p>${reviews.length ? reviews.map(r => reviewCard(r,p)).join('') : '<div class="inline-empty">Este perfil ainda não tem avaliações. Elas aparecem após um serviço concluído.</div>'}</section></div></div><aside class="contact-panel"><h2>Vamos conversar sobre o seu serviço?</h2><p>Conte o que você precisa e combine os detalhes diretamente com o profissional.</p><button class="btn btn-primary btn-block" data-contact="${esc(id)}">${icon('message',21)} Conversar no WhatsApp</button><p class="small-note">Cadastro gratuito para entrar em contato e registrar seu serviço.</p><div class="contact-detail">${icon('check',19)} <span>Valores e visita combinados diretamente.</span></div><div class="contact-detail">${icon('calendar',19)} <span>Registre o serviço para acompanhar e avaliar depois.</span></div><div class="contact-detail">${icon('shield',19)} <span>Assinatura não é selo de qualificação.</span></div><p class="demo-contact">${icon('info',17)} A prévia simula o contato. Não abre um WhatsApp real.</p></aside></div></section>`;
  }
  function loginPage(params) {return `<section class="container page-section auth-page"><div class="auth-copy">${pageIntro('Seu próximo encontro começa aqui.', 'Com uma conta gratuita, você registra o serviço e compartilha como foi a experiência.')}<div class="auth-benefits"><p>${icon('message',23)} Converse com o profissional.</p><p>${icon('calendar',23)} Acompanhe o que foi combinado.</p><p>${icon('star',23)} Avalie depois do serviço.</p></div></div><div class="form-panel"><h2>Entre para explorar</h2><p>Escolha uma conta de exemplo para experimentar o protótipo.</p><button class="btn btn-primary btn-block" data-demo-login="client" data-next="${esc(params.get('next') || '')}" data-pro="${esc(params.get('id') || '')}">${icon('user',20)} Entrar como cliente de exemplo</button><button class="btn btn-outline btn-block" data-demo-login="professional" data-next="${esc(params.get('next') || '')}" data-pro="${esc(params.get('id') || '')}">${icon('engineering',20)} Entrar como profissional de exemplo</button>${state.professionalAccount ? '<button class="btn btn-outline btn-block" data-local-login>Voltar ao perfil profissional criado nesta sessão</button>' : ''}<div class="form-divider"><span>ou experimente o cadastro</span></div><a class="btn btn-outline btn-block" href="${routeLink('/cadastro',{role:'client',next:params.get('next') || '',id:params.get('id') || ''})}">Criar cadastro de cliente</a><a class="auth-switch" href="#/cadastro?role=professional">Quero cadastrar meus serviços</a>${demoNote('Não há autenticação real nesta prévia. As contas de exemplo não usam senha e valem apenas nesta sessão.')}</div></section>`;}
  function registrationPage(params) {
    const isPro = params.get('role') === 'professional';
    const edit = params.get('edit') === '1';
    if(edit && (!isPro || !ownsLocalProfile())) return `<section class="container page-section narrow-page">${pageIntro('Entre na conta responsável pelo perfil.', 'A edição está disponível somente para o profissional que criou este perfil nesta sessão.', '/entrar')}<a class="btn btn-primary" href="#/entrar">Escolher conta de demonstração</a></section>`;
    if(isPro && !edit && state.profile) return `<section class="container page-section narrow-page">${pageIntro('Seu perfil de demonstração já foi criado.', 'Esta prévia permite um perfil profissional próprio por sessão. Volte à conta criada para editar seus dados; ao recarregar, a demonstração é reiniciada.', '/entrar')}<button class="btn btn-primary" data-local-login>Voltar ao perfil profissional criado</button></section>`;
    const p = edit ? state.profile : null;
    state.photo = p?.photo || (p?.demoPhoto ? 'demo' : null);
    return `<section class="container page-section registration-page">${pageIntro(isPro ? 'Mostre o que você sabe fazer.' : 'Encontre. Combine. Avalie.', isPro ? 'Seu perfil reúne suas habilidades, seus trabalhos e as cidades que você atende.' : 'Seu cadastro é gratuito. Ele conecta você ao registro do serviço e às suas avaliações.')}<div class="registration-layout"><form id="registration-form" class="form-panel" data-role="${isPro ? 'professional' : 'client'}" data-edit="${edit ? '1' : '0'}" data-next="${esc(params.get('next') || '')}" data-pro="${esc(params.get('id') || '')}"><h2>${edit ? 'Editar meu perfil' : isPro ? 'Cadastro do profissional' : 'Cadastro do cliente'}</h2>${demoNote()}<div class="form-error" role="alert" tabindex="-1"></div>${isPro ? `<div class="photo-field"><div id="photo-preview" class="photo-preview">${p ? portrait(p) : icon('camera',30)}</div><div><label for="profile-photo" class="file-label">${icon('upload',17)} Adicionar minha foto <span>*</span></label><input id="profile-photo" name="photo" type="file" accept="image/png,image/jpeg,image/webp" aria-describedby="photo-help"><p id="photo-help" class="field-help">Foto obrigatória · JPG, PNG ou WebP · até 2 MB</p><button type="button" class="text-button" data-example-photo>Usar foto de demonstração</button></div></div>` : ''}<div class="form-grid"><label>Nome completo <span>*</span><input name="name" autocomplete="off" required minlength="3" maxlength="90" placeholder="Ex.: Alex de Exemplo" value="${esc(p?.name || '')}"></label><label>E-mail <span>*</span><input name="email" type="email" autocomplete="off" required maxlength="120" placeholder="exemplo@email.com" value="${esc(edit ? state.user.email : '')}"></label></div><label>Cidade ${isPro ? 'onde você mora' : ''} <span>*</span><select name="city" required>${cityOptions(p?.city || '',false)}</select></label>${isPro ? `<label>Como você apresenta seu trabalho? <span>*</span><input name="title" required maxlength="100" placeholder="Ex.: Eletricista e instalador de pisos" value="${esc(p?.title || '')}"></label><label>Conte sobre você e seu trabalho <span>*</span><textarea name="description" required minlength="30" maxlength="1200" rows="4" placeholder="Explique os serviços que faz e como costuma trabalhar.">${esc(p?.description || '')}</textarea><small class="field-help">Mínimo de 30 caracteres. Descreva sua experiência sem incluir dados privados.</small></label><fieldset><legend>Em quais categorias você atua? <span>*</span></legend><p class="field-help">Selecione todas que representam os serviços que você executa.</p><div class="category-checkboxes">${D.categories.map(c => `<label class="check-option"><input type="checkbox" name="categories" value="${c.id}" ${p?.categories.includes(c.id) ? 'checked' : ''}>${icon(c.icon,19)}<span>${c.name}</span></label>`).join('')}</div></fieldset><label>Quais trabalhos e habilidades você oferece? <span>*</span><textarea name="skills" required maxlength="600" rows="3" placeholder="Ex.: instalação elétrica, troca de tomadas, instalação de porcelanato">${esc(p?.skills.join(', ') || '')}</textarea><small class="field-help">Separe os serviços por vírgulas. Eles também ajudam as pessoas a encontrar você.</small></label><fieldset><legend>Quais cidades você atende? <span>*</span></legend><p class="field-help">Você pode atender várias cidades, mesmo morando em outra.</p><div class="city-checkboxes">${D.cities.map(c => `<label><input type="checkbox" name="cities" value="${esc(c)}" ${p?.cities.includes(c) ? 'checked' : ''}> ${esc(c)}</label>`).join('')}</div></fieldset><div class="notice"><strong>Os valores ficam na conversa.</strong><p>Preço do serviço e eventual taxa de visita serão combinados pelo WhatsApp. Seu perfil não exibe preço mínimo ou máximo.</p></div>` : ''}<label class="consent"><input type="checkbox" name="consent" required><span>Entendo que este é um protótipo local e que devo usar dados fictícios.</span></label><button type="submit" class="btn btn-primary btn-block">${edit ? 'Salvar alterações da prévia' : 'Criar cadastro de demonstração'} ${icon('arrow',20)}</button></form><aside class="registration-aside"><h2>${isPro ? 'Uma pessoa. Muitas habilidades.' : 'Sua experiência também ajuda outras pessoas.'}</h2><p>${isPro ? 'Arquiteto e engenheiro? Mestre de obras e pedreiro? Seu perfil pode aparecer em todas as categorias em que você atua.' : 'O cadastro vincula você ao serviço registrado. Depois da conclusão, você poderá avaliar e adicionar fotos.'}</p><div class="aside-icon">${icon(isPro ? 'engineering' : 'star',60)}</div><ul><li>Foto e apresentação no perfil profissional.</li><li>Atendimento organizado por cidade.</li><li>Avaliações vinculadas aos serviços.</li></ul><a href="${isPro ? '#/cadastro?role=client' : '#/cadastro?role=professional'}">${isPro ? 'Estou procurando um profissional' : 'Quero anunciar meus serviços'} ${icon('arrow',17)}</a></aside></div></section>`;
  }
  function clientSwitchPage(id) {return `<section class="container page-section narrow-page">${pageIntro('Experimente o contato como cliente.', 'Você está usando uma conta profissional. Troque explicitamente para a conta de cliente de exemplo para registrar este pedido.', '/profissional/'+id)}<button class="btn btn-primary" data-demo-login="client" data-next="contato" data-pro="${esc(id)}">Trocar para cliente e continuar</button>${demoNote('O perfil e a assinatura do profissional permanecem associados à conta profissional nesta sessão.')}</section>`;}
  function servicePage(id) {
    const p = professional(id); if (!p) return notFound();
    if (!state.user) return loginPage(new URLSearchParams({next:'contato',id}));
    if (state.user.role !== 'client') return clientSwitchPage(id);
    return `<section class="container page-section narrow-page">${pageIntro('Deixe o combinado registrado.', 'Este pedido cria um registro para acompanhar o serviço. Ele ainda precisa ser confirmado pelo profissional.', '/profissional/'+id)}<div class="service-pro">${portrait(p)}<div><strong>${esc(p.name)}</strong><span>${esc(p.title)}</span></div></div><form class="form-panel" id="service-form" data-pro="${esc(id)}"><div class="form-error" role="alert" tabindex="-1"></div><label>Qual serviço você precisa? <span>*</span><input name="title" required minlength="5" maxlength="120" placeholder="Ex.: revisão elétrica da cozinha"></label><label>Conte um pouco mais <span>*</span><textarea name="description" required minlength="10" maxlength="1000" rows="4" placeholder="Descreva o que precisa ser feito, sem incluir endereço completo ou dados sensíveis."></textarea></label><label>Cidade do serviço <span>*</span><select name="city" required><option value="">Selecione a cidade</option>${p.cities.map(c => `<option>${esc(c)}</option>`).join('')}</select></label><div class="notice"><strong>Preço e data são combinados na conversa.</strong><p>Na versão funcional, você seguirá para o WhatsApp. Aqui, nenhum contato real será aberto.</p></div><button class="btn btn-primary btn-block" type="submit">${icon('message',20)} Registrar pedido e simular contato</button>${demoNote('Registrar um pedido ou clicar no WhatsApp não comprova contratação, pagamento ou execução do serviço.')}</form></section>`;
  }
  const statuses = {requested:'Aguardando confirmação',confirmed:'Serviço confirmado',professional_completed:'Aguardando sua confirmação',completed:'Concluído',disputed:'Em contestação'};
  function serviceCard(s) {const p=professional(s.proId); const review = state.reviews.find(r => r.serviceId === s.id);return `<article class="service-card"><div class="service-card-top"><span class="status-pill status-${s.status}">${statuses[s.status]}</span><small>Registro ${esc(s.id)}</small></div><h3>${esc(s.title)}</h3><p>${esc(p?.name || 'Profissional')} · ${esc(s.city)}</p><p class="muted">${esc(s.description)}</p><div class="service-actions">${s.status === 'requested' ? `<button class="btn btn-outline" data-job="${s.id}" data-job-action="confirm">Simular aceite do profissional</button>` : ''}${s.status === 'confirmed' ? `<button class="btn btn-outline" data-job="${s.id}" data-job-action="pro-complete">Simular conclusão pelo profissional</button>` : ''}${s.status === 'professional_completed' ? `<button class="btn btn-primary" data-job="${s.id}" data-job-action="complete">Confirmar conclusão e avaliar</button><button class="btn btn-outline" data-job="${s.id}" data-job-action="dispute">Há um problema com o serviço</button>` : ''}${s.status === 'completed' ? review ? `<a class="btn btn-outline" href="#/profissional/${s.proId}">Ver minha avaliação</a><span class="reviewed-label">${icon('check',17)} Avaliação enviada</span>` : `<a class="btn btn-primary" href="#/avaliar/${s.id}">Avaliar profissional</a><p class="small-note">Como foi o serviço? Sua avaliação está pendente.</p>` : ''}${s.status === 'disputed' ? `<p class="small-note">Relato registrado nesta sessão. Uma equipe de atendimento precisará analisar o caso no sistema real.</p>` : ''}</div></article>`;}
  function accountPage() {
    if (!state.user) return loginPage(new URLSearchParams());
    const pro = state.user.role === 'professional'; const p = professional(state.user.proId);
    const ownProfile = ownsLocalProfile();
    const services = state.services.filter(s => s.clientId === state.user.id);
    return `<section class="container page-section account-page"><div class="account-heading"><div>${pageIntro(`Olá, ${esc(state.user.name.split(' ')[0])}.`, pro ? 'Seu espaço para apresentar seu trabalho e acompanhar sua presença no Achei Quem.' : 'Acompanhe seus serviços e conte como foi a experiência.')}</div><button class="text-button" data-logout>${icon('logout',18)} Sair da conta de exemplo</button></div>${demoNote()}${pro ? `<div class="dashboard-grid"><section class="dashboard-profile"><div class="dashboard-avatar">${portrait(p)}</div><h2>${esc(p.name)}</h2><p>${esc(p.title)}</p><div class="pro-tags">${tags(p)}</div><p class="small-note">${ownProfile ? state.profile.status === 'published' ? 'Perfil publicado apenas nesta demonstração.' : 'Cadastro aguardando análise na demonstração.' : 'Perfil ilustrativo de profissional.'}</p>${ownProfile ? '<a class="btn btn-outline btn-block" href="#/cadastro?role=professional&edit=1">Editar meu perfil</a>' : ''}<a class="text-button" href="#/profissional/${p.id}">Ver perfil público ${icon('arrow',17)}</a></section><section class="subscription-panel"><h2>Sua assinatura</h2><span class="status-pill">${currentSubscription() === 'active' ? 'Ativa na demonstração' : currentSubscription() === 'canceled' ? 'Renovação cancelada na demonstração' : 'Ainda não ativada'}</span><p>A mensalidade é paga ao Achei Quem pela divulgação do seu perfil. Você recebe pelo serviço diretamente do cliente, fora da plataforma.</p><a class="btn btn-primary" href="#/planos">${currentSubscription() === 'active' ? 'Gerenciar assinatura' : 'Conhecer o plano'}</a>${ownProfile && state.profile.status !== 'published' ? `<div class="demo-tools"><p>Teste a aprovação administrativa depois de ativar a assinatura simulada.</p><button class="text-button" data-approve-profile>Simular aprovação do cadastro</button></div>` : ''}</section></div><div class="account-secondary"><h2>Experimente também como cliente</h2><p>Para testar registro do serviço e avaliação, use a conta de cliente de exemplo.</p><button class="btn btn-outline" data-demo-login="client">Trocar para cliente de exemplo</button></div>` : `<div class="section-title-row"><h2>Meus serviços</h2><a class="btn btn-outline" href="#/buscar">${icon('plus',17)} Encontrar profissional</a></div>${services.length ? `<div class="services-list">${services.map(serviceCard).join('')}</div>` : `<div class="empty-state">${icon('calendar',43)}<h2>Seu primeiro serviço começa com uma conversa.</h2><p>Encontre um profissional, registre o que você precisa e acompanhe por aqui.</p><a class="btn btn-primary" href="#/buscar">Encontrar profissionais ${icon('arrow',20)}</a></div>`}<p class="small-note">Os botões “Simular” representam ações da outra parte apenas para testar o fluxo. No sistema real, cada ação terá sua própria autorização.</p>`}</section>`;
  }
  function reviewPage(id) {
    const s = state.services.find(job => job.id === id);
    if (state.user?.role !== 'client' || !s || s.clientId !== state.user.id || s.status !== 'completed') return `<section class="container page-section narrow-page">${pageIntro('A avaliação começa com um serviço concluído.', 'Só o cliente vinculado ao registro pode avaliar. Confirme a conclusão do serviço no seu painel.', '/conta')}<a class="btn btn-primary" href="#/conta">Ir para meus serviços</a></section>`;
    if (state.reviews.some(r => r.serviceId === id)) return `<section class="container page-section narrow-page">${pageIntro('Você já avaliou este serviço.', 'Cada registro recebe uma avaliação do cliente.', '/conta')}<a class="btn btn-primary" href="#/profissional/${s.proId}">Ver avaliação no perfil</a></section>`;
    const p = professional(s.proId);
    return `<section class="container page-section narrow-page">${pageIntro('Como foi o serviço?', 'Seu relato ajuda outras pessoas a escolher. Conte o que aconteceu com clareza e respeito.', '/conta')}<div class="service-pro">${portrait(p)}<div><strong>${esc(p.name)}</strong><span>${esc(s.title)}</span></div></div><form id="review-form" class="form-panel" data-service="${esc(id)}"><div class="form-error" role="alert" tabindex="-1"></div><fieldset class="rating-field"><legend>Sua nota <span>*</span></legend><div class="rating-options">${[1,2,3,4,5].map(n => `<label><input type="radio" name="score" value="${n}" required><span>${icon('star',26)}<strong>${n}</strong></span></label>`).join('')}</div><p class="field-help">1 = muito insatisfeito · 5 = muito satisfeito</p></fieldset><label>Conte como foi <span>*</span><textarea name="text" required minlength="15" maxlength="1500" rows="5" placeholder="O que foi combinado? Como foi a execução? Houve algo que poderia melhorar?"></textarea></label><label>Fotos do serviço <span class="optional">opcional</span><input name="photos" type="file" accept="image/png,image/jpeg,image/webp" multiple data-review-photos><small class="field-help">Até 3 fotos, 2 MB cada. Evite rostos, documentos, endereços e outros dados privados.</small></label><div id="review-photo-preview" class="review-photos"></div><label class="consent"><input name="consent" type="checkbox" required><span>Meu relato se refere a este serviço e as imagens não expõem dados pessoais de terceiros.</span></label><button class="btn btn-primary btn-block" type="submit">Publicar avaliação na prévia ${icon('arrow',19)}</button>${demoNote('Sua avaliação ficará apenas nesta sessão local. No produto real, haverá política de moderação, resposta e contestação.')}</form></section>`;
  }
  function plansPage() {return `<section class="container page-section plans-page">${pageIntro('Seu trabalho merece ser encontrado.', 'Uma assinatura para apresentar suas habilidades nas cidades que você atende.')}<div class="plan-layout"><div class="plan-pitch"><h2>Você faz o serviço.<br>Seu perfil conta a sua história.</h2><p>Foto, habilidades, trabalhos e avaliações reunidos em um só lugar.</p><div class="plan-people">${D.professionals.slice(0,3).map(p => portrait(p)).join('')}</div><p class="small-note">Retratos e perfis ilustrativos.</p></div><div class="plan-card"><span class="plan-label">Plano profissional</span><h2>Mensalidade</h2><p class="price-pending">Valor a definir</p><p>O preço será definido antes do lançamento comercial.</p><ul>${['Perfil com foto e apresentação','Várias categorias e habilidades','Múltiplas cidades atendidas','Portfólio e avaliações dos clientes','Contato direto pelo WhatsApp'].map(t => `<li>${icon('check',19)}${t}</li>`).join('')}</ul><button class="btn btn-primary btn-block" data-subscribe>${currentSubscription() === 'active' ? 'Assinatura ativa na demonstração' : 'Experimentar assinatura simulada'} ${icon('arrow',19)}</button>${currentSubscription() === 'active' ? '<button class="text-button cancel-subscription" data-cancel-subscription>Simular cancelamento da renovação</button>' : ''}<p class="small-note">Nenhum cartão é solicitado e nenhum valor é cobrado.</p></div></div><div class="notice"><strong>O pagamento do serviço continua entre vocês.</strong><p>A assinatura remunera o Achei Quem pela divulgação. Recebimentos de serviços dentro do aplicativo são uma evolução futura.</p></div></section>`;}
  function howPage() {return `<section class="container page-section how-page">${pageIntro('Do “preciso de alguém” ao “achei quem”.', 'Um caminho simples para encontrar, combinar e compartilhar sua experiência.')}<div class="how-flow">${[['search','Encontre a pessoa certa','Busque por serviço, habilidade e cidade. Compare os perfis e veja onde cada profissional atende.'],['user','Crie sua conta gratuita','Seu cadastro vincula você ao registro do serviço e à avaliação depois da conclusão.'],['message','Converse e registre','Combine valores e detalhes pelo WhatsApp. Registre o serviço e aguarde a confirmação do profissional.'],['star','Conte como foi','Após a conclusão confirmada, deixe sua nota, seu relato e fotos do serviço.']].map(([i,t,p],index) => `<article><span class="step-number">${index+1}</span>${icon(i,30)}<h2>${t}</h2><p>${p}</p></article>`).join('')}</div><div class="how-bottom"><div><h2>Você tem mais de uma habilidade?</h2><p>Seu perfil pode aparecer em várias categorias. Um profissional pode ser arquiteto e engenheiro, ou executar elétrica e acabamentos.</p></div><a class="btn btn-primary" href="#/cadastro?role=professional">Criar perfil profissional ${icon('arrow',20)}</a></div><div class="notice"><strong>Avaliações fazem parte do histórico.</strong><p>Relatos negativos e positivos são permitidos. O profissional pode responder e qualquer usuário cadastrado pode denunciar conteúdo abusivo ou que exponha dados pessoais. Uma crítica não é removida apenas por ser negativa.</p></div></section>`;}
  function aboutPage() {return `<section class="container page-section narrow-page">${pageIntro('Uma prévia para decidir juntos.', 'Três propostas visuais, um mesmo produto. As interações são simuladas no seu navegador, sem conexão com serviços de produção.')}<div class="form-panel"><h2>O que você pode experimentar</h2><ul class="plain-list"><li>Trocar entre Praça, Bora resolver e Perto de você na barra superior.</li><li>Buscar profissionais por habilidade, categoria e cidade atendida.</li><li>Cadastrar um perfil com foto, múltiplas categorias e cidades.</li><li>Usar uma conta de exemplo, registrar um serviço, simular sua conclusão e publicar uma avaliação com fotos.</li><li>Simular assinatura, cancelamento, resposta e denúncia.</li></ul><h2>O que ainda será implementado</h2><p>Autenticação segura, banco de dados, mensagens reais, cobrança, armazenamento permanente, confirmação por contas independentes e moderação operacional.</p><h2>Privacidade nesta prévia</h2><p>Use somente dados fictícios. Cadastros e fotos adicionados ficam na memória desta aba e desaparecem ao recarregar. Apenas a preferência visual pode ser salva no navegador.</p><h2>Cobertura de demonstração</h2><p>O seletor inclui 35 municípios do interior da região, incluindo cidades serranas. A lista comercial definitiva será conferida com você; as cidades do Litoral Norte não foram incluídas nesta prévia.</p><h2>Identidade em exploração</h2><p>A logo enviada foi preservada. As aplicações de cores, tipografia e composição são propostas. O manual completo será elaborado após a escolha visual.</p><a class="btn btn-primary" href="#/inicio">Voltar às três prévias ${icon('arrow',20)}</a></div></section>`;}
  function notFound() {return `<section class="container page-section empty-state"><h1>Não encontramos esta página.</h1><p>Volte para a busca e encontre um profissional.</p><a class="btn btn-primary" href="#/buscar">Ir para a busca</a></section>`;}
  function render() {
    const {path,params} = currentRoute();
    document.body.dataset.theme = theme;
    document.querySelectorAll('[data-theme-choice]').forEach(b => b.setAttribute('aria-pressed',String(b.dataset.themeChoice === theme)));
    const account = $('#account-link'); account.textContent = state.user ? 'Minha conta' : 'Entrar'; account.href=state.user ? '#/conta' : '#/entrar';
    let html;
    if(path === '/inicio' || path === '/') html = window.AQHome ? window.AQHome.render(theme) : `<section class="container page-section"><h1>Encontre quem resolve.</h1><a href="#/buscar" class="btn btn-primary">Buscar profissionais</a></section>`;
    else if(path === '/buscar') html = searchPage(params);
    else if(path.startsWith('/profissional/')) html = profilePage(decodeURIComponent(path.split('/')[2]));
    else if(path === '/entrar') html = loginPage(params);
    else if(path === '/cadastro') html = registrationPage(params);
    else if(path.startsWith('/registrar-servico/')) html = servicePage(decodeURIComponent(path.split('/')[2]));
    else if(path === '/conta') html = accountPage();
    else if(path.startsWith('/avaliar/')) html = reviewPage(path.split('/')[2]);
    else if(path === '/planos') html = plansPage();
    else if(path === '/como-funciona') html = howPage();
    else if(path === '/sobre-prototipo') html = aboutPage();
    else html=notFound();
    $('#main').innerHTML=html;
    document.title = `${$('#main h1')?.textContent || 'Encontre quem resolve'} | Achei Quem`;
    window.scrollTo({top:0,behavior:'instant'});
    $('#main').focus({preventScroll:true});
  }
  function modal(title,body) {$('#dialog-content').innerHTML=`<button class="dialog-close" data-close-dialog aria-label="Fechar">${icon('close',22)}</button><h2 id="dialog-title">${title}</h2>${body}`;$('#app-dialog').showModal();}
  function closeModal() {$('#app-dialog').close();}
  function formError(form, message) {const el=$('.form-error',form); if(el){el.textContent=message;el.classList.add('shown');el.focus();} else toast(message);}
  async function readPhoto(file) {
    if(!file || !['image/jpeg','image/png','image/webp'].includes(file.type)) throw new Error('Escolha uma imagem JPG, PNG ou WebP.');
    if(file.size > 2*1024*1024) throw new Error('Cada imagem deve ter no máximo 2 MB.');
    const data=await new Promise((resolve,reject) => {const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('Não foi possível ler essa imagem.'));r.readAsDataURL(file);});
    await new Promise((resolve,reject) => {const im=new Image();im.onload=()=>im.width && im.height ? resolve() : reject(new Error('Imagem inválida.'));im.onerror=()=>reject(new Error('Este arquivo não contém uma imagem válida.'));im.src=data;});
    return data;
  }
  function finishLogin(role, next, proId) {state.user=role==='professional'?{id:'demo-professional',name:'Rafael Almeida',email:'profissional@exemplo.test',role,proId:'rafael'}:{id:'demo-client',name:'Alex Exemplo',email:'cliente@exemplo.test',role}; go(next==='contato' && professional(proId) ? '/registrar-servico/'+proId : '/conta');toast('Conta de demonstração iniciada.');}
  document.addEventListener('click', event => {
    const target=event.target.closest('button,a'); if(!target) return;
    if(target.matches('[data-theme-choice]')) {theme=target.dataset.themeChoice;try{localStorage.setItem('aq-concept',theme); const u=new URL(location.href);u.searchParams.set('concept',theme);history.replaceState({},'',u);}catch{} go('/inicio');render();return;}
    if(target.getAttribute('href') === '#main') {event.preventDefault();$('#main').focus({preventScroll:true});$('#main').scrollIntoView({behavior:'instant'});return;}
    if(target.getAttribute('href') === '#reviews') {event.preventDefault();$('#reviews')?.scrollIntoView({behavior:'smooth'});return;}
    if(target.matches('[data-local-login]')) {if(state.professionalAccount){state.user={...state.professionalAccount};go('/conta');toast('Perfil profissional desta sessão retomado.');}return;}
    if(target.matches('[data-demo-login]')) {finishLogin(target.dataset.demoLogin,target.dataset.next,target.dataset.pro);return;}
    if(target.matches('[data-contact]')) {const id=target.dataset.contact;go(state.user ? '/registrar-servico/'+id : '/entrar?next=contato&id='+id);return;}
    if(target.matches('[data-logout]')) {state.user=null;go('/inicio');toast('Você saiu da conta de exemplo.');return;}
    if(target.matches('[data-example-photo]')) {state.photo='demo';$('#photo-preview').innerHTML='<span class="portrait portrait-0" role="img" aria-label="Foto fictícia de demonstração"></span>';$('#profile-photo').value='';return;}
    if(target.matches('[data-close-dialog]')) {closeModal();return;}
    if(target.matches('[data-subscribe]')) {if(!state.user || state.user.role!=='professional'){go('/cadastro?role=professional');toast('Cadastre seu perfil profissional para experimentar a assinatura.');return;}if(currentSubscription()==='active'){toast('Sua assinatura de demonstração já está ativa.');return;}modal('Ativar assinatura de demonstração',`<p>O plano será mensal. O preço e o meio de cobrança ainda serão definidos.</p><div class="notice"><strong>Nenhuma cobrança será feita.</strong><p>Esta ação apenas muda o estado da assinatura nesta aba.</p></div><button class="btn btn-primary btn-block" data-confirm-subscribe>Ativar na demonstração</button>`);return;}
    if(target.matches('[data-confirm-subscribe]')) {if(state.user?.role!=='professional') return;state.subscriptions[state.user.proId]='active';closeModal();go('/conta');toast('Assinatura simulada ativada. Nenhuma cobrança realizada.');return;}
    if(target.matches('[data-cancel-subscription]')) {if(state.user?.role!=='professional') return;modal('Cancelar renovação na prévia?',`<p>Esta ação demonstra o cancelamento. Não existe cobrança ou contrato real nesta sessão.</p><button class="btn btn-primary btn-block" data-confirm-cancel>Confirmar cancelamento simulado</button>`);return;}
    if(target.matches('[data-confirm-cancel]')) {if(state.user?.role!=='professional') return;state.subscriptions[state.user.proId]='canceled';closeModal();go('/conta');toast('Renovação cancelada na demonstração.');return;}
    if(target.matches('[data-approve-profile]')) {if(!ownsLocalProfile()) return;if(currentSubscription()!=='active'){toast('Ative a assinatura simulada antes de publicar o perfil de demonstração.');return;}if(state.profile){state.profile.status='published';render();toast('Aprovação administrativa simulada. Seu perfil aparece na busca local.');}return;}
    if(target.matches('[data-job]')) {
      const s=state.services.find(j=>j.id===target.dataset.job);if(state.user?.role!=='client' || !s || s.clientId!==state.user.id) return;
      const action=target.dataset.jobAction;
      if(action==='confirm' && s.status==='requested') {s.status='confirmed';render();toast('Aceite do profissional simulado.');}
      if(action==='pro-complete' && s.status==='confirmed') {s.status='professional_completed';render();toast('Conclusão informada pelo profissional na simulação.');}
      if(action==='complete' && s.status==='professional_completed') {s.status='completed';go('/avaliar/'+s.id);}
      if(action==='dispute' && s.status==='professional_completed') modal('O que precisa ser resolvido?',`<form id="dispute-form" data-service="${s.id}"><label>Descreva o problema<textarea name="reason" required minlength="10" maxlength="1000" rows="4"></textarea></label><p class="field-help">O relato fica registrado. Uma contestação não publica uma acusação automaticamente.</p><button class="btn btn-primary" type="submit">Registrar contestação na prévia</button></form>`);
      return;
    }
    if(target.matches('[data-report]')) {if(!state.user){toast('Entre em uma conta de exemplo para registrar a denúncia.');go('/entrar');return;}modal('Denunciar uma avaliação',`<form id="report-form" data-review="${esc(target.dataset.report)}"><p>Relatos negativos são permitidos. Denúncias são analisadas pelo conteúdo, não pela nota.</p><label>Motivo<select name="reason" required><option value="">Selecione</option><option>Exposição de dados pessoais</option><option>Ofensa ou ameaça</option><option>Spam ou conteúdo fora do serviço</option><option>Outro problema</option></select></label><label>Conte o que aconteceu<textarea name="details" required minlength="10" maxlength="800" rows="3"></textarea></label><button class="btn btn-primary" type="submit">Registrar denúncia na prévia</button></form>`);return;}
    if(target.matches('[data-respond]')) {const r=[...D.reviews,...state.reviews].find(r=>r.id===target.dataset.respond);if(!r || state.user?.role!=='professional' || state.user.proId!==r.proId) return;modal('Responder à avaliação',`<form id="response-form" data-review="${esc(r.id)}"><label>Sua resposta<textarea name="response" required minlength="10" maxlength="1000" rows="4" placeholder="Responda ao relato com respeito e sem expor dados privados."></textarea></label><button class="btn btn-primary" type="submit">Publicar resposta na prévia</button></form>`);}
  });
  document.addEventListener('change',async event => {
    const input=event.target;
    if(input.id==='profile-photo' && input.files[0]) {try{state.photo=await readPhoto(input.files[0]);$('#photo-preview').innerHTML=`<img src="${state.photo}" alt="Prévia da foto selecionada">`;}catch(error){state.photo=null;input.value='';$('#photo-preview').innerHTML=icon('camera',30);formError(input.form,error.message);}}
    if(input.matches('[data-review-photos]')) {try{if(input.files.length>3) throw new Error('Selecione no máximo 3 fotos.');const photos=await Promise.all([...input.files].map(readPhoto));$('#review-photo-preview').innerHTML=photos.map((p,i)=>`<img src="${p}" alt="Prévia da foto ${i+1}">`).join('');}catch(error){input.value='';$('#review-photo-preview').innerHTML='';formError(input.form,error.message);}}
  });
  document.addEventListener('submit',async event => {
    const form=event.target;event.preventDefault();const data=new FormData(form);
    if(form.matches('[data-search-form]')) {const q=new URLSearchParams();for(const key of ['term','city','category']){const value=String(data.get(key)||'').trim();if(value) q.set(key,value);}go('/buscar'+(q.size?'?'+q:''));return;}
    if(!form.reportValidity()) return;
    if(form.id==='registration-form') {
      const isPro=form.dataset.role==='professional';const editing=form.dataset.edit==='1';const cats=data.getAll('categories');const cities=data.getAll('cities');
      if(editing && (!isPro || !ownsLocalProfile())) return formError(form,'Entre na conta responsável pelo perfil para editar.');
      if(isPro && !editing && state.profile) return formError(form,'Esta prévia mantém um perfil profissional próprio por sessão. Volte à conta criada para editá-lo.');
      const name=String(data.get('name')||'').trim();const email=String(data.get('email')||'').trim().toLowerCase();
      const title=String(data.get('title')||'').trim();const description=String(data.get('description')||'').trim();
      if(name.length<3) return formError(form,'Informe um nome com pelo menos 3 caracteres, além de espaços.');
      if(isPro && (title.length<3 || description.length<30)) return formError(form,'Informe uma apresentação válida e uma descrição com pelo menos 30 caracteres, além de espaços.');
      if(isPro && !state.photo) return formError(form,'Adicione sua foto ou escolha a foto de demonstração.');
      if(isPro && !cats.length) return formError(form,'Selecione pelo menos uma categoria de atuação.');
      if(isPro && !cities.length) return formError(form,'Selecione pelo menos uma cidade atendida.');
      const skills=String(data.get('skills')||'').split(/[,;\n]/).map(s=>s.trim()).filter(Boolean);
      if(isPro && (!skills.length || skills.some(s=>s.length<3))) return formError(form,'Descreva cada habilidade com pelo menos 3 caracteres, separando por vírgulas.');
      const id = isPro ? 'local-professional' : clientIdFor(email);
      state.user={id,name,email,role:form.dataset.role,city:String(data.get('city')),proId:isPro?'meu-perfil':undefined};
      if(isPro) {state.profile={id:'meu-perfil',name,title,description,categories:cats,skills:[...new Set(skills)],cities,city:state.user.city,photo:state.photo==='demo'?null:state.photo,demoPhoto:state.photo==='demo',photoIndex:0,projects:skills.slice(0,2),status:state.profile?.status||'review'};state.professionalAccount={...state.user};}
      go(!isPro && form.dataset.next==='contato' && professional(form.dataset.pro) ? '/registrar-servico/'+form.dataset.pro : '/conta');toast(isPro ? 'Perfil salvo na demonstração local.' : 'Cadastro de exemplo criado.');return;
    }
    if(form.id==='service-form') {if(!state.user) return go('/entrar?next=contato&id='+encodeURIComponent(form.dataset.pro));if(state.user.role!=='client') return formError(form,'Troque para uma conta de cliente antes de registrar o pedido.');const title=String(data.get('title')||'').trim();const description=String(data.get('description')||'').trim();if(title.length<5 || description.length<10) return formError(form,'Descreva o serviço com pelo menos 5 caracteres no título e 10 na descrição, além de espaços.');const p=professional(form.dataset.pro);if(!p || !p.cities.includes(String(data.get('city')))) return formError(form,'Escolha uma cidade atendida pelo profissional.');state.services.unshift({id:'AQ-'+String(state.services.length+1).padStart(3,'0'),clientId:state.user.id,proId:p.id,title,description,city:String(data.get('city')),status:'requested'});go('/conta');toast('Pedido registrado na prévia. Nenhum WhatsApp foi aberto.');return;}
    if(form.id==='review-form') {
      const s=state.services.find(j=>j.id===form.dataset.service);
      if(state.user?.role!=='client' || !s || s.clientId!==state.user.id || s.status!=='completed' || state.reviews.some(r=>r.serviceId===s.id)) return formError(form,'Este registro não está disponível para avaliação.');
      if(String(data.get('text')||'').trim().length<15) return formError(form,'Conte sua experiência em pelo menos 15 caracteres, além de espaços.');
      const files=[...form.elements.photos.files];if(files.length>3) return formError(form,'Selecione até 3 fotos.');
      const button=$('button[type="submit"]',form);button.disabled=true;button.textContent='Preparando avaliação…';
      try {const photos=await Promise.all(files.map(readPhoto));state.reviews.unshift({id:'local-'+Date.now(),serviceId:s.id,proId:s.proId,author:state.user.name+' · demonstração',score:Number(data.get('score')),service:s.title,date:'2026-10-29',text:String(data.get('text')).trim(),photos});go('/profissional/'+s.proId);toast('Avaliação adicionada apenas nesta sessão local.');}catch(error){button.disabled=false;button.textContent='Publicar avaliação na prévia';formError(form,error.message);}return;
    }
    if(form.id==='dispute-form') {const s=state.services.find(j=>j.id===form.dataset.service);if(state.user?.role==='client' && s && s.clientId===state.user.id && s.status==='professional_completed'){s.status='disputed';s.dispute=String(data.get('reason')).trim();closeModal();render();toast('Contestação registrada nesta sessão.');}return;}
    if(form.id==='report-form') {if(!state.user) return;state.reports.push({reviewId:form.dataset.review,userId:state.user.id,reason:String(data.get('reason')),details:String(data.get('details'))});closeModal();toast('Denúncia registrada localmente. A avaliação permanece visível até análise.');return;}
    if(form.id==='response-form') {const r=[...D.reviews,...state.reviews].find(r=>r.id===form.dataset.review);if(r && state.user?.role==='professional' && state.user.proId===r.proId){r.response=String(data.get('response')).trim();closeModal();render();toast('Resposta adicionada nesta demonstração.');}}
  });
  window.addEventListener('hashchange',()=>{if($('#app-dialog').open) closeModal();render();});
  render();
})();
